target.css:
:root {
  --ink: #283626;
  --olive: #53662b;
  --olive-dark: #34451d;
  --cream: #fffdf5;
  --canvas: #f1eddb;
  --line: #d7d0b7;
  --gold: #d99428;
  --peach: #fff0d3;
  --muted: #78806d;
  --white: #ffffff;
}

* {
  box-sizing: border-box;
}

.press-card {
  width: 500px;
  overflow: hidden;
  color: var(--ink);
  background: var(--cream);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px 12px;
  border-bottom: 1px solid var(--line);
}

.identity {
  min-width: 0;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

h1,
h2,
p {
  margin-top: 0;
}

h1 {
  margin-bottom: 0;
  font-size: 21px;
  line-height: 1;
  letter-spacing: -0.04em;
}

.batch-badge {
  margin: 0;
  padding: 6px 9px;
  color: var(--olive-dark);
  background: var(--canvas);
  border: 1px solid var(--line);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 800;
  white-space: nowrap;
}

.content {
  display: grid;
  grid-template-columns: 0.88fr 1.12fr;
}

.vat-summary {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px;
  background: var(--canvas);
  border-right: 1px solid var(--line);
}

.gauge {
  display: flex;
  flex: 0 0 76px;
  width: 76px;
  height: 76px;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  margin: 0;
  color: var(--cream);
  background: var(--olive);
  border: 5px solid var(--olive-dark);
  border-radius: 50%;
}

.gauge span {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.gauge strong {
  font-size: 20px;
  line-height: 1;
  letter-spacing: -0.06em;
}

.metrics {
  display: grid;
  gap: 7px;
  margin: 0;
}

.metrics div {
  display: grid;
  gap: 1px;
}

.metrics dt {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  line-height: 1;
  text-transform: uppercase;
}

.metrics dd {
  margin: 0;
  font-size: 12px;
  font-weight: 800;
  line-height: 1.15;
}

.run-sheet {
  padding: 12px 15px 10px;
}

.section-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 7px;
}

.section-heading h2 {
  margin: 0;
  font-size: 13px;
  letter-spacing: -0.02em;
}

.section-heading span {
  padding: 3px 7px;
  color: var(--olive-dark);
  background: var(--peach);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
}

.steps {
  display: grid;
  gap: 5px;
  padding: 0;
  margin: 0;
  list-style: none;
}

.steps li {
  display: flex;
  align-items: center;
  gap: 8px;
}

.steps i {
  display: block;
  flex: 0 0 9px;
  width: 9px;
  height: 9px;
  background: var(--white);
  border: 2px solid var(--line);
  border-radius: 50%;
}

.steps .complete i {
  background: var(--olive);
  border-color: var(--olive);
}

.steps .active i {
  background: var(--gold);
  border-color: var(--gold);
}

.steps p {
  display: flex;
  min-width: 0;
  align-items: baseline;
  justify-content: space-between;
  gap: 7px;
  margin: 0;
  font-size: 11px;
  line-height: 1.2;
}

.steps strong {
  font-weight: 800;
  white-space: nowrap;
}

.steps small {
  color: var(--muted);
  font-size: 10px;
  white-space: nowrap;
}

.release-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 9px 14px 9px 16px;
  background: var(--olive-dark);
}

.release-bar p {
  margin: 0;
  color: var(--cream);
  font-size: 11px;
}

.release-bar button {
  padding: 7px 10px;
  color: var(--olive-dark);
  background: var(--cream);
  border: 0;
  border-radius: 7px;
  font-size: 11px;
  font-weight: 800;
}

